async (args) => {
  /* Click "query" */
  const $ = async (s, ms = 8000) => { const t = Date.now(); while (Date.now() - t < ms) { const e = document.querySelector(s); if (e) return e; await new Promise((r) => setTimeout(r, 100)); } throw new Error("element not found: " + s); };
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const el = await $("#query");
  el.scrollIntoView({ block: "center" });
  el.click();
}

async (args) => {
  /* Set "query" to "blue" */
  const $ = async (s, ms = 8000) => { const t = Date.now(); while (Date.now() - t < ms) { const e = document.querySelector(s); if (e) return e; await new Promise((r) => setTimeout(r, 100)); } throw new Error("element not found: " + s); };
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  await wait(807);
  const el = await $("#query");
  el.focus();
  const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), "value");
  if (d && d.set) d.set.call(el, "blue"); else el.value = "blue";
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
}

